#include "simp/CodeGenerator.hpp"

#include "simp/Diagnostic.hpp"

#include <algorithm>
#include <sstream>
#include <stdexcept>
#include <utility>

namespace simp {

CodeGenerator::CodeGenerator(std::string targetTriple)
    : targetTriple_(std::move(targetTriple)) {}

bool CodeGenerator::isArrayType(const std::string& type) const {
    return type == "array";
}

bool CodeGenerator::isMapType(const std::string& type) const {
    return type == "map";
}

bool CodeGenerator::isDynamicValueType(const std::string& type) const {
    return type == "any";
}

bool CodeGenerator::isManagedReferenceType(const std::string& type) const {
    return isArrayType(type) || isMapType(type) || classes_.find(type) != classes_.end();
}

[[noreturn]] void CodeGenerator::unsupported(const SourceLocation& location,
                                             const std::string& feature) const {
    throw DiagnosticError(location, feature + " is not supported by the current LLVM backend");
}

std::string CodeGenerator::newTemporary() {
    return "%t" + std::to_string(nextTemporary_++);
}

CodeGenerator::Value CodeGenerator::rootObjectValue(Value value,
                                                     const SourceLocation& location) {
    if (isDynamicValueType(value.type)) {
        // A dynamic 'any' value may embed a managed-reference pointer (or may not,
        // if it holds an int/string/null). Root the pointer sub-field so a later
        // allocation cannot collect a referenced object out from under it; unlike
        // a plain object/array reference, we cannot call simp_gc_require_alive
        // here because the pointer may instead be string byte data that the GC
        // heap does not manage.
        const auto pointer = newTemporary();
        instructions_ += "  " + pointer + " = extractvalue %SimpleArrayValue " + value.operand +
                         ", 2\n";
        const auto slot = "%root." + std::to_string(nextRoot_++);
        entryAllocas_ += "  " + slot + " = alloca ptr\n";
        instructions_ += "  store ptr " + pointer + ", ptr " + slot + "\n";
        rootSlots_.push_back(slot);
        return value;
    }
    if (!isManagedReferenceType(value.type) || value.operand == "null") {
        return value;
    }
    const auto file = internString(location.file);
    instructions_ += "  call void @simp_gc_require_alive(ptr " + value.operand +
                     ", ptr " + file + ", i64 " +
                     std::to_string(location.file.size()) + ", i64 " +
                     std::to_string(location.line) + ", i64 " +
                     std::to_string(location.column) + ")\n";
    const auto slot = "%root." + std::to_string(nextRoot_++);
    entryAllocas_ += "  " + slot + " = alloca ptr\n";
    instructions_ += "  store ptr " + value.operand + ", ptr " + slot + "\n";
    rootSlots_.push_back(slot);
    return value;
}

void CodeGenerator::registerRootSlot(const std::string& pointer, const std::string& type) {
    if (isDynamicValueType(type)) {
        // The variable's own storage is a %SimpleArrayValue aggregate; only its
        // pointer sub-field can ever hold a GC reference, so root that sub-field
        // directly inside the variable's alloca rather than the whole aggregate.
        const auto slot = "%vroot" + std::to_string(nextRoot_++);
        entryAllocas_ += "  " + slot + " = getelementptr inbounds %SimpleArrayValue, ptr " +
                         pointer + ", i32 0, i32 2\n";
        rootSlots_.push_back(slot);
        return;
    }
    if (isManagedReferenceType(type)) {
        rootSlots_.push_back(pointer);
    }
}

std::string CodeGenerator::freshLabel(const std::string& prefix) {
    return prefix + "." + std::to_string(nextLabel_++);
}

std::string CodeGenerator::llvmType(const std::string& type) const {
    if (type == "int") return "i32";
    if (type == "string") return "%SimpleString";
    if (type == "any") return "%SimpleArrayValue";
    if (type == "void") return "void";
    return "ptr";
}

std::string CodeGenerator::methodSymbol(const std::string& className,
                                       const std::string& methodName) const {
    return "@simp." + className + "." + methodName;
}

void CodeGenerator::emitNullCheck(const std::string& pointer,
                                 const SourceLocation& location) {
    const auto file = internString(location.file);
    instructions_ += "  call void @simp.require_nonnull(ptr " + pointer + ", ptr " +
                     file + ", i64 " + std::to_string(location.file.size()) +
                     ", i64 " + std::to_string(location.line) + ", i64 " +
                     std::to_string(location.column) + ")\n";
}

CodeGenerator::Value CodeGenerator::emitIntegerExpression(const Expression& expression) {
    if (expression.kind == ExpressionKind::Integer) return {"int", expression.value};
    const auto value = emitExpression(expression);
    if (value.type != "int") {
        throw DiagnosticError(expression.location, "integer expression required");
    }
    return value;
}

void CodeGenerator::emitArrayElementStore(const std::string& valuePointer, Value value,
                                          const SourceLocation& location) {
    const auto dynamic = buildDynamicValue(std::move(value), location);
    instructions_ += "  store %SimpleArrayValue " + dynamic.operand + ", ptr " + valuePointer +
                     "\n";
}

void CodeGenerator::emitMapElementStore(const std::string& mapPointer, Value key, Value value,
                                        const SourceLocation& location) {
    const auto keyData = newTemporary();
    const auto keyLength = newTemporary();
    instructions_ += "  " + keyData + " = extractvalue %SimpleString " + key.operand + ", 0\n"
                     "  " + keyLength + " = extractvalue %SimpleString " + key.operand + ", 1\n";
    const auto dynamic = buildDynamicValue(std::move(value), location);
    const auto valueSlot = newTemporary();
    entryAllocas_ += "  " + valueSlot + " = alloca %SimpleArrayValue\n";
    instructions_ += "  store %SimpleArrayValue " + dynamic.operand + ", ptr " + valueSlot +
                     "\n";
    const auto file = internString(location.file);
    instructions_ += "  call void @simp_map_set(ptr " + mapPointer + ", ptr " + keyData +
                     ", i64 " + keyLength + ", ptr " + valueSlot +
                     ", ptr " + file + ", i64 " +
                     std::to_string(location.file.size()) + ", i64 " +
                     std::to_string(location.line) + ", i64 " +
                     std::to_string(location.column) + ")\n";
}

CodeGenerator::Value CodeGenerator::buildDynamicValue(Value value,
                                                       const SourceLocation& location) {
    (void)location;
    if (value.type == "any") {
        return value;
    }
    if (value.operand == "null") {
        value.type = "null";
    }
    const auto tag = newTemporary();
    instructions_ += "  " + tag + " = insertvalue %SimpleArrayValue zeroinitializer, i64 " +
                     (value.type == "int" ? "1" : value.type == "string" ? "2" :
                      isMapType(value.type) ? "4" : isArrayType(value.type) ? "5" : "3") +
                     ", 0\n";
    std::string stored = tag;
    if (value.type == "int") {
        const auto extended = newTemporary();
        const auto withInteger = newTemporary();
        instructions_ += "  " + extended + " = sext i32 " + value.operand + " to i64\n"
                         "  " + withInteger + " = insertvalue %SimpleArrayValue " + stored +
                         ", i64 " + extended + ", 1\n";
        stored = withInteger;
    } else if (value.type == "string") {
        const auto data = newTemporary();
        const auto length = newTemporary();
        const auto withData = newTemporary();
        const auto withLength = newTemporary();
        instructions_ += "  " + data + " = extractvalue %SimpleString " + value.operand +
                         ", 0\n"
                         "  " + length + " = extractvalue %SimpleString " + value.operand +
                         ", 1\n"
                         "  " + withData + " = insertvalue %SimpleArrayValue " + stored +
                         ", ptr " + data + ", 2\n"
                         "  " + withLength + " = insertvalue %SimpleArrayValue " + withData +
                         ", i64 " + length + ", 3\n";
        stored = withLength;
    } else if (value.type == "null") {
        // Tagged as an object reference with a null pointer: assignable to any
        // class-typed extraction target, matching a null class reference.
    } else {
        const auto withPointer = newTemporary();
        instructions_ += "  " + withPointer + " = insertvalue %SimpleArrayValue " + stored +
                         ", ptr " + value.operand + ", 2\n";
        stored = withPointer;
    }
    return {"any", stored};
}

CodeGenerator::Value CodeGenerator::extractTypedValue(Value value,
                                                       const std::string& expectedType,
                                                       const SourceLocation& location) {
    const auto file = internString(location.file);
    const auto fileLength = std::to_string(location.file.size());
    const auto line = std::to_string(location.line);
    const auto column = std::to_string(location.column);
    const auto tag = newTemporary();
    instructions_ += "  " + tag + " = extractvalue %SimpleArrayValue " + value.operand + ", 0\n";
    if (expectedType == "int") {
        instructions_ += "  call void @simp_value_require_tag(i64 " + tag + ", i64 1, ptr " +
                         file + ", i64 " + fileLength + ", i64 " + line + ", i64 " + column +
                         ")\n";
        const auto stored = newTemporary();
        const auto result = newTemporary();
        instructions_ += "  " + stored + " = extractvalue %SimpleArrayValue " + value.operand +
                         ", 1\n"
                         "  " + result + " = trunc i64 " + stored + " to i32\n";
        return {"int", result};
    }
    if (expectedType == "string") {
        instructions_ += "  call void @simp_value_require_tag(i64 " + tag + ", i64 2, ptr " +
                         file + ", i64 " + fileLength + ", i64 " + line + ", i64 " + column +
                         ")\n";
        const auto pointer = newTemporary();
        const auto length = newTemporary();
        const auto first = newTemporary();
        const auto result = newTemporary();
        instructions_ += "  " + pointer + " = extractvalue %SimpleArrayValue " + value.operand +
                         ", 2\n"
                         "  " + length + " = extractvalue %SimpleArrayValue " + value.operand +
                         ", 3\n"
                         "  " + first + " = insertvalue %SimpleString poison, ptr " + pointer +
                         ", 0\n"
                         "  " + result + " = insertvalue %SimpleString " + first + ", i64 " +
                         length + ", 1\n";
        return {"string", result};
    }
    if (expectedType == "map" || expectedType == "array") {
        const auto pointer = newTemporary();
        instructions_ += "  " + pointer + " = extractvalue %SimpleArrayValue " +
                         value.operand + ", 2\n"
                         "  call void @simp_value_require_" + expectedType +
                         "(i64 " + tag + ", ptr " + pointer + ", ptr " + file +
                         ", i64 " + fileLength + ", i64 " + line + ", i64 " + column +
                         ")\n";
        return {expectedType, rootObjectValue({expectedType, pointer}, location).operand};
    }
    // Otherwise expectedType names a class: the value must tag as an object
    // reference, and (unless it is null) its runtime class metadata must match
    // exactly. This prototype does not support extracting a proper subclass
    // instance into a base-class-typed variable from 'any'.
    const auto pointer = newTemporary();
    instructions_ += "  " + pointer + " = extractvalue %SimpleArrayValue " + value.operand +
                     ", 2\n"
                     "  call void @simp_value_require_class(i64 " + tag + ", ptr " + pointer +
                     ", ptr @.simp.class.meta." + expectedType + ", ptr " + file + ", i64 " +
                     fileLength + ", i64 " + line + ", i64 " + column + ")\n";
    return rootObjectValue({expectedType, pointer}, location);
}

std::string CodeGenerator::rootFrameInitialization() const {
    std::ostringstream setup;
    setup << "  %simp.root.frame = alloca %SimpRootFrame\n";
    if (!rootSlots_.empty()) {
        setup << "  %simp.root.slots = alloca [" << rootSlots_.size() << " x ptr]\n";
    }
    for (std::size_t index = 0; index < rootSlots_.size(); ++index) {
        const auto slotAddress = "%simp.root.slot.addr." + std::to_string(index);
        setup << "  store ptr null, ptr " << rootSlots_[index] << "\n"
              << "  " << slotAddress << " = getelementptr inbounds [" << rootSlots_.size()
              << " x ptr], ptr %simp.root.slots, i64 0, i64 " << index << "\n"
              << "  store ptr " << rootSlots_[index] << ", ptr " << slotAddress << "\n";
    }
    return setup.str();
}

std::string CodeGenerator::rootFramePush() const {
    std::ostringstream setup;
    setup << "  call void @simp_gc_push_or_abort(ptr %simp.root.frame, ptr "
          << (rootSlots_.empty() ? "null" : "%simp.root.slots") << ", i64 "
          << rootSlots_.size() << ")\n";
    return setup.str();
}

void CodeGenerator::emitRootFramePop() {
    instructions_ += "  call void @simp_gc_pop_or_abort(ptr %simp.root.frame)\n";
}

CodeGenerator::Value CodeGenerator::emitExpression(const Expression& expression,
                                                   const std::string& expectedType) {
    switch (expression.kind) {
    case ExpressionKind::Integer:
        return {"int", expression.value};
    case ExpressionKind::String: {
        const auto global = internString(expression.value);
        const auto pointer = newTemporary();
        instructions_ += "  " + pointer + ".data = getelementptr inbounds [" +
                         std::to_string(expression.value.size()) + " x i8], ptr " + global +
                         ", i64 0, i64 0\n";
        const auto first = newTemporary();
        const auto result = newTemporary();
        instructions_ += "  " + first + " = insertvalue %SimpleString poison, ptr " + pointer +
                         ".data, 0\n";
        instructions_ += "  " + result + " = insertvalue %SimpleString " + first + ", i64 " +
                         std::to_string(expression.value.size()) + ", 1\n";
        return {"string", result};
    }
    case ExpressionKind::Null:
        return {expectedType.empty() ? "null" : expectedType, "null"};
    case ExpressionKind::ArrayLiteral: {
        const auto array = newTemporary();
        instructions_ += "  " + array + " = call ptr @simp_gc_alloc_array(i64 " +
                         std::to_string(expression.arguments.size()) + ")\n";
        rootObjectValue({"array", array}, expression.location);
        for (std::size_t index = 0; index < expression.arguments.size(); ++index) {
            const auto element = emitExpression(*expression.arguments[index]);
            const auto valueIndex = newTemporary();
            const auto valuePointer = newTemporary();
            instructions_ += "  " + valueIndex + " = getelementptr inbounds %SimpleArray, ptr " +
                             array + ", i32 0, i32 2, i64 " + std::to_string(index) + "\n"
                             "  " + valuePointer +
                             " = getelementptr inbounds %SimpleArrayValue, ptr " + valueIndex +
                             ", i32 0\n";
            emitArrayElementStore(valuePointer, element, expression.arguments[index]->location);
        }
        return {"array", array};
    }
    case ExpressionKind::MapLiteral: {
        const auto map = newTemporary();
        instructions_ += "  " + map + " = call ptr @simp_gc_alloc_map()\n";
        rootObjectValue({"map", map}, expression.location);
        for (std::size_t index = 0; index < expression.arguments.size(); index += 2) {
            const auto key = emitExpression(*expression.arguments[index]);
            const auto value = emitExpression(*expression.arguments[index + 1]);
            emitMapElementStore(map, key, value, expression.arguments[index]->location);
        }
        return {"map", map};
    }
    case ExpressionKind::Identifier: {
        const auto binding = findVariable(expression.value, expression.location);
        const auto pointer = emitAddress(binding, expression.location);
        const auto result = newTemporary();
        instructions_ += "  " + result + " = load " + llvmType(binding.type) + ", ptr " +
                         pointer + "\n";
        return rootObjectValue({binding.type, result}, expression.location);
    }
    case ExpressionKind::Member: {
        const Expression* root = nullptr;
        const ClassDeclaration* owner = nullptr;
        std::vector<std::string> basePath;
        const bool qualified =
            resolveBaseQualifier(*expression.left, root, owner, basePath);
        const auto receiver = qualified ? Value{} : emitExpression(*expression.left);
        if (!qualified && isArrayType(receiver.type)) {
            if (expression.value != "length") {
                throw DiagnosticError(expression.location,
                                      "arrays support only the read-only 'length' member");
            }
            const auto lengthAddress = newTemporary();
            const auto length = newTemporary();
            const auto result = newTemporary();
            instructions_ += "  " + lengthAddress +
                             " = getelementptr inbounds %SimpleArray, ptr " + receiver.operand +
                             ", i32 0, i32 1\n"
                             "  " + length + " = load i64, ptr " + lengthAddress + "\n"
                             "  " + result + " = trunc i64 " + length + " to i32\n";
            return {"int", result};
        }
        if (!qualified && isMapType(receiver.type)) {
            if (expression.value != "length") {
                throw DiagnosticError(expression.location,
                                      "maps support only the read-only 'length' member");
            }
            const auto lengthAddress = newTemporary();
            const auto length = newTemporary();
            const auto result = newTemporary();
            instructions_ += "  " + lengthAddress +
                             " = getelementptr inbounds %SimpleMap, ptr " + receiver.operand +
                             ", i32 0, i32 1\n"
                             "  " + length + " = load i64, ptr " + lengthAddress + "\n"
                             "  " + result + " = trunc i64 " + length + " to i32\n";
            return {"int", result};
        }
        const auto object = qualified ? emitExpression(*root) : receiver;
        if (classes_.find(object.type) == classes_.end()) {
            throw DiagnosticError(expression.location, "member receiver is not an object");
        }
        emitNullCheck(object.operand, expression.location);
        auto objectView = object.operand;
        if (!qualified) {
            owner = classes_.at(object.type);
        } else {
            objectView = emitSubobjectAddress(object.operand, *classes_.at(object.type),
                                              basePath);
        }
        std::vector<std::size_t> fieldPath;
        const auto* field = findField(*owner, expression.value, fieldPath);
        if (field == nullptr) {
            throw DiagnosticError(expression.location,
                                  "class '" + owner->name + "' has no field '" + expression.value + "'");
        }
        const auto address = emitFieldAddress(objectView, *owner, fieldPath);
        const auto result = newTemporary();
        instructions_ += "  " + result + " = load " + llvmType(field->type) + ", ptr " +
                         address + "\n";
        return rootObjectValue({field->type, result}, expression.location);
    }
    case ExpressionKind::Index: {
        const auto collection = emitExpression(*expression.left);
        const auto file = internString(expression.location.file);
        const auto valuePointer = newTemporary();
        const auto loaded = newTemporary();
        if (isArrayType(collection.type)) {
            const auto index = emitIntegerExpression(*expression.arguments.front());
            instructions_ += "  " + valuePointer + " = call ptr @simp_array_index(ptr " +
                             collection.operand + ", i32 " + index.operand + ", ptr " + file +
                             ", i64 " +
                             std::to_string(expression.location.file.size()) + ", i64 " +
                             std::to_string(expression.location.line) + ", i64 " +
                             std::to_string(expression.location.column) + ")\n"
                             "  " + loaded + " = load %SimpleArrayValue, ptr " +
                             valuePointer + "\n";
        } else {
            const auto key = emitExpression(*expression.arguments.front());
            const auto keyData = newTemporary();
            const auto keyLength = newTemporary();
            instructions_ += "  " + keyData + " = extractvalue %SimpleString " + key.operand +
                             ", 0\n"
                             "  " + keyLength + " = extractvalue %SimpleString " + key.operand +
                             ", 1\n"
                             "  " + valuePointer + " = call ptr @simp_map_get(ptr " +
                             collection.operand + ", ptr " + keyData + ", i64 " + keyLength +
                             ", ptr " + file + ", i64 " +
                             std::to_string(expression.location.file.size()) + ", i64 " +
                             std::to_string(expression.location.line) + ", i64 " +
                             std::to_string(expression.location.column) + ")\n"
                             "  " + loaded + " = load %SimpleArrayValue, ptr " +
                             valuePointer + "\n";
        }
        // Indexing an array always yields the dynamic 'any' representation; the
        // same dynamic result is used for maps; typed consumers extract it.
        return rootObjectValue({"any", loaded}, expression.location);
    }
    case ExpressionKind::Slice: {
        const auto array = emitExpression(*expression.left);
        const auto start = emitIntegerExpression(*expression.arguments[0]);
        const auto end = emitIntegerExpression(*expression.arguments[1]);
        const auto file = internString(expression.location.file);
        const auto result = newTemporary();
        instructions_ += "  " + result + " = call ptr @simp_array_slice(ptr " + array.operand +
                         ", i32 " + start.operand + ", i32 " + end.operand + ", ptr " + file +
                         ", i64 " + std::to_string(expression.location.file.size()) +
                         ", i64 " + std::to_string(expression.location.line) + ", i64 " +
                         std::to_string(expression.location.column) + ")\n";
        return rootObjectValue({array.type, result}, expression.location);
    }
    case ExpressionKind::ConstructorCall: {
        const auto found = classes_.find(expression.value);
        if (found == classes_.end()) {
            throw DiagnosticError(expression.location, "unknown class '" + expression.value + "'");
        }
        const auto* owner = found->second;
        const auto object = newTemporary();
        instructions_ += "  " + object + " = call ptr @simp_gc_alloc(ptr @.simp.class.meta." +
                         owner->name + ")\n";
        rootObjectValue({owner->name, object}, expression.location);
        emitNullCheck(object, expression.location);
        const auto rootLink = newTemporary();
        instructions_ += "  " + rootLink + " = getelementptr inbounds %Class." +
                         owner->name + ", ptr " + object + ", i32 0, i32 1\n"
                         "  store ptr " + object + ", ptr " + rootLink + "\n";
        for (const auto& view : subobjects(*owner)) {
            const auto viewAddress = emitSubobjectAddress(object, *owner, view.first);
            for (const auto& baseName : virtualBaseNames(*view.second)) {
                const auto canonicalAddress = newTemporary();
                const auto slotAddress = newTemporary();
                instructions_ += "  " + canonicalAddress + " = getelementptr inbounds %Class." +
                                 owner->name + ", ptr " + object + ", i32 0, i32 " +
                                 std::to_string(virtualBaseStorageIndex(*owner, baseName)) +
                                 "\n"
                                 "  " + slotAddress + " = getelementptr inbounds %Class." +
                                 view.second->name + ", ptr " + viewAddress + ", i32 0, i32 " +
                                 std::to_string(virtualBasePointerIndex(*view.second, baseName)) +
                                 "\n"
                                 "  store ptr " + canonicalAddress + ", ptr " + slotAddress +
                                 "\n";
            }
        }
        for (const auto& view : subobjects(*owner)) {
            if (view.first.empty()) continue;
            const auto viewAddress = emitSubobjectAddress(object, *owner, view.first);
            const auto metadataAddress = newTemporary();
            const auto ownerLinkAddress = newTemporary();
            instructions_ += "  " + metadataAddress + " = getelementptr inbounds %Class." +
                                 view.second->name + ", ptr " + viewAddress + ", i32 0, i32 0\n"
                                 "  store ptr " + viewMetadataSymbol(*owner, view.first) +
                                 ", ptr " + metadataAddress + "\n"
                                 "  " + ownerLinkAddress + " = getelementptr inbounds %Class." +
                                 view.second->name + ", ptr " + viewAddress + ", i32 0, i32 1\n"
                                 "  store ptr " + object + ", ptr " + ownerLinkAddress + "\n";
        }
        const MethodDeclaration* constructor = nullptr;
        for (const auto& method : owner->methods) {
            if (method.constructor) {
                constructor = &method;
                break;
            }
        }
        std::vector<std::pair<const ClassDeclaration*, std::string>> virtualConstructors;
        for (const auto& baseName : virtualBaseNames(*owner)) {
            const auto* base = classes_.at(baseName);
            for (const auto& method : base->methods) {
                if (method.constructor) {
                    virtualConstructors.emplace_back(base, method.name);
                    break;
                }
            }
        }
        if (constructor != nullptr || !virtualConstructors.empty()) {
            instructions_ += "  call void @simp_gc_begin_construction(ptr " + object + ")\n";
        }
        if (constructor == nullptr) {
            for (const auto& virtualConstructor : virtualConstructors) {
                const auto virtualAddress = newTemporary();
                instructions_ += "  " + virtualAddress + " = getelementptr inbounds %Class." +
                                 owner->name + ", ptr " + object + ", i32 0, i32 " +
                                 std::to_string(virtualBaseStorageIndex(
                                     *owner, virtualConstructor.first->name)) +
                                 "\n  call void " +
                                 methodSymbol(virtualConstructor.first->name,
                                              virtualConstructor.second) +
                                 "(ptr " + virtualAddress + ", i1 false)\n";
            }
        }
        for (const auto& method : owner->methods) {
            if (!method.constructor) continue;
            std::string arguments = "ptr " + object + ", i1 true";
            for (std::size_t index = 0; index < expression.arguments.size(); ++index) {
                const auto value = emitExpression(*expression.arguments[index],
                                                  method.parameters[index].type);
                const auto converted = convertObjectValue(value, method.parameters[index].type,
                                                           expression.arguments[index]->location);
                arguments += ", " + llvmType(method.parameters[index].type) + " " +
                             converted.operand;
            }
            instructions_ += "  call void " + methodSymbol(owner->name, method.name) +
                             "(" + arguments + ")\n";
            break;
        }
        if (constructor != nullptr || !virtualConstructors.empty()) {
            instructions_ += "  call void @simp_gc_end_construction(ptr " + object + ")\n";
        }
        return {owner->name, object};
    }
    case ExpressionKind::Call: {
        if (expression.left->kind != ExpressionKind::Member) {
            throw DiagnosticError(expression.location, "only object method calls are supported");
        }
        const auto& target = *expression.left;
        const Expression* root = nullptr;
        const ClassDeclaration* owner = nullptr;
        std::vector<std::string> basePath;
        const bool qualified = resolveBaseQualifier(*target.left, root, owner, basePath);
        auto receiver = emitExpression(qualified ? *root : *target.left);
        if (isMapType(receiver.type)) {
            if (target.value != "contains" || expression.arguments.size() != 1) {
                throw DiagnosticError(target.location,
                                      "maps support only 'contains(string)'");
            }
            const auto key = emitExpression(*expression.arguments.front());
            const auto keyData = newTemporary();
            const auto keyLength = newTemporary();
            const auto file = internString(target.location.file);
            const auto result = newTemporary();
            instructions_ += "  " + keyData + " = extractvalue %SimpleString " + key.operand +
                             ", 0\n"
                             "  " + keyLength + " = extractvalue %SimpleString " + key.operand +
                             ", 1\n"
                             "  " + result + " = call i32 @simp_map_contains(ptr " +
                             receiver.operand + ", ptr " + keyData + ", i64 " + keyLength +
                             ", ptr " + file + ", i64 " +
                             std::to_string(target.location.file.size()) + ", i64 " +
                             std::to_string(target.location.line) + ", i64 " +
                             std::to_string(target.location.column) + ")\n";
            return {"int", result};
        }
        const auto found = classes_.find(receiver.type);
        if (found == classes_.end()) {
            throw DiagnosticError(target.location, "method receiver is not an object");
        }
        emitNullCheck(receiver.operand, target.location);
        if (!qualified) {
            owner = found->second;
        } else {
            receiver = {owner->name,
                        emitSubobjectAddress(receiver.operand, *found->second, basePath)};
        }
        if (target.value == "destroy") {
            if (qualified) {
                throw DiagnosticError(target.location,
                                      "qualified destructor calls are not supported");
            }
            const auto findDestructor = [this](const auto& self,
                                               const ClassDeclaration& declaration)
                -> const MethodDeclaration* {
                for (const auto& candidate : declaration.methods) {
                    if (candidate.destructor) return &candidate;
                }
                for (const auto& baseName : declaration.baseClassNames) {
                    const auto base = classes_.find(baseName);
                    if (base != classes_.end()) {
                        if (const auto* inherited = self(self, *base->second))
                            return inherited;
                    }
                }
                return nullptr;
            };
            const auto* destructor = findDestructor(findDestructor, *owner);
            if (destructor == nullptr) {
                throw DiagnosticError(target.location,
                                      "class '" + owner->name + "' has no destructor");
            }
            const auto file = internString(target.location.file);
            instructions_ += "  call void @simp_gc_begin_destroy(ptr " + receiver.operand +
                             ", ptr " + file + ", i64 " +
                             std::to_string(target.location.file.size()) + ", i64 " +
                             std::to_string(target.location.line) + ", i64 " +
                             std::to_string(target.location.column) + ")\n";
            const auto metadata = newTemporary();
            const auto finalizerAddress = newTemporary();
            const auto finalizer = newTemporary();
            const auto rootObject = newTemporary();
            instructions_ += "  " + metadata + " = load ptr, ptr " + receiver.operand + "\n"
                             "  " + finalizerAddress +
                             " = getelementptr inbounds %SimpleClassMeta, ptr " + metadata +
                             ", i32 0, i32 8\n"
                             "  " + finalizer + " = load ptr, ptr " + finalizerAddress + "\n"
                             "  " + rootObject + " = call ptr @simp_gc_root(ptr " +
                             receiver.operand + ")\n"
                             "  call void " + finalizer + "(ptr " + rootObject + ")\n";
            instructions_ += "  call void @simp_gc_end_destroy(ptr " +
                             rootObject + ")\n";
            return {"void", ""};
        }
        const auto* method = findMethod(*owner, target.value);
        if (method == nullptr) {
            throw DiagnosticError(target.location,
                                  "class '" + owner->name + "' has no method '" + target.value + "'");
        }
        std::string arguments = "ptr " + receiver.operand;
        for (std::size_t index = 0; index < expression.arguments.size(); ++index) {
            const auto value = emitExpression(*expression.arguments[index], method->parameters[index].type);
            const auto converted = convertObjectValue(value, method->parameters[index].type,
                                                       expression.arguments[index]->location);
            arguments += ", " + llvmType(method->parameters[index].type) + " " +
                         converted.operand;
        }
        const auto metadata = newTemporary();
        instructions_ += "  " + metadata + " = load ptr, ptr " + receiver.operand + "\n";
        const auto tableAddress = newTemporary();
        instructions_ += "  " + tableAddress +
                         " = getelementptr inbounds %SimpleClassMeta, ptr " + metadata +
                         ", i32 0, i32 3\n";
        const auto table = newTemporary();
        instructions_ += "  " + table + " = load ptr, ptr " + tableAddress + "\n";
        const auto entry = newTemporary();
        instructions_ += "  " + entry + " = getelementptr inbounds %SimpleMethodMeta, ptr " +
        table + ", i64 " + std::to_string(methodSlot(*owner, target.value)) +
                         "\n";
        const auto functionAddress = newTemporary();
        instructions_ += "  " + functionAddress +
                         " = getelementptr inbounds %SimpleMethodMeta, ptr " + entry +
                         ", i32 0, i32 2\n";
        const auto function = newTemporary();
        instructions_ += "  " + function + " = load ptr, ptr " + functionAddress + "\n";
        if (method->returnType == "void") {
            instructions_ += "  call void " + function + "(" + arguments + ")\n";
            return {"void", ""};
        }
        const auto result = newTemporary();
        instructions_ += "  " + result + " = call " + llvmType(method->returnType) + " " +
                         function + "(" + arguments + ")\n";
        return rootObjectValue({method->returnType, result}, expression.location);
    }
    case ExpressionKind::Unary: {
        const auto operand = emitIntegerExpression(*expression.left);
        if (expression.value == "+") return operand;
        const auto result = newTemporary();
        if (expression.value == "-") {
            instructions_ += "  " + result + " = sub i32 0, " + operand.operand + "\n";
        } else {
            const auto flag = newTemporary();
            instructions_ += "  " + flag + " = icmp eq i32 " + operand.operand + ", 0\n";
            instructions_ += "  " + result + " = zext i1 " + flag + " to i32\n";
        }
        return {"int", result};
    }
    case ExpressionKind::Binary: {
        const auto left = emitIntegerExpression(*expression.left);
        const auto right = emitIntegerExpression(*expression.right);
        const auto result = newTemporary();
        const auto& operation = expression.value;
        if (operation == "+" || operation == "-" || operation == "*") {
            const char* instruction = operation == "+" ? "add" : operation == "-" ? "sub" : "mul";
            instructions_ += "  " + result + " = " + instruction + " i32 " + left.operand +
                             ", " + right.operand + "\n";
            return {"int", result};
        }
        if (operation == "/" || operation == "%") {
            const auto zero = newTemporary();
            const auto failureLabel = freshLabel("division.zero");
            const auto successLabel = freshLabel("division.ok");
            instructions_ += "  " + zero + " = icmp eq i32 " + right.operand + ", 0\n"
                             "  br i1 " + zero + ", label %" + failureLabel +
                             ", label %" + successLabel + "\n"
                             + failureLabel + ":\n"
                             "  call void @simp_exception_raise(ptr @.simp.division.message, i64 16, ptr " +
                             internString(expression.location.file) + ", i64 " +
                             std::to_string(expression.location.file.size()) + ", i64 " +
                             std::to_string(expression.location.line) + ", i64 " +
                             std::to_string(expression.location.column) + ")\n"
                             "  unreachable\n"
                             + successLabel + ":\n";
            const char* instruction = operation == "/" ? "sdiv" : "srem";
            instructions_ += "  " + result + " = " + instruction + " i32 " + left.operand +
                             ", " + right.operand + "\n";
            return {"int", result};
        }
        std::string predicate;
        if (operation == "==") predicate = "eq";
        else if (operation == "!=") predicate = "ne";
        else if (operation == "<") predicate = "slt";
        else if (operation == "<=") predicate = "sle";
        else if (operation == ">") predicate = "sgt";
        else if (operation == ">=") predicate = "sge";
        else unsupported(expression.location, "operator '" + operation + "'");
        const auto flag = newTemporary();
        instructions_ += "  " + flag + " = icmp " + predicate + " i32 " + left.operand +
                         ", " + right.operand + "\n";
        instructions_ += "  " + result + " = zext i1 " + flag + " to i32\n";
        return {"int", result};
    }
    }
    unsupported(expression.location, "expression");
}

} // namespace simp
